#include "channel.h"
#include <stdint.h>
static void copy_in(uint8_t*d,const uint8_t*s,size_t n){for(size_t i=0;i<n;i++)d[i]=s[i];}
void ipc_channel_init(rix_ipc_channel_t*c){if(!c)return;c->head=c->tail=c->count=0;c->closed=0;rix_spin_init(&c->lock);}
int ipc_write(rix_ipc_channel_t*c,const void*buf,size_t n,size_t*w){if(w)*w=0;if(!c||(!buf&&n))return -1;uint64_t f;rix_spin_lock_irqsave(&c->lock,&f);if(c->closed){rix_spin_unlock_irqrestore(&c->lock,f);return -2;}size_t m=n;if(m>RIX_IPC_CAPACITY-c->count)m=RIX_IPC_CAPACITY-c->count;const uint8_t*s=(const uint8_t*)buf;size_t a=m;if(a>RIX_IPC_CAPACITY-c->tail)a=RIX_IPC_CAPACITY-c->tail;copy_in(c->data+c->tail,s,a);if(m>a)copy_in(c->data,s+a,m-a);c->tail=(c->tail+m)%RIX_IPC_CAPACITY;c->count+=m;if(w)*w=m;rix_spin_unlock_irqrestore(&c->lock,f);return m==n?0:-3;}
int ipc_read(rix_ipc_channel_t*c,void*buf,size_t n,size_t*r){if(r)*r=0;if(!c||(!buf&&n))return -1;uint64_t f;rix_spin_lock_irqsave(&c->lock,&f);size_t m=n;if(m>c->count)m=c->count;uint8_t*d=(uint8_t*)buf;size_t a=m;if(a>RIX_IPC_CAPACITY-c->head)a=RIX_IPC_CAPACITY-c->head;copy_in(d,c->data+c->head,a);if(m>a)copy_in(d+a,c->data,m-a);c->head=(c->head+m)%RIX_IPC_CAPACITY;c->count-=m;if(r)*r=m;int rc=!m&&c->closed?-2:(m==n?0:-3);rix_spin_unlock_irqrestore(&c->lock,f);return rc;}
int ipc_close(rix_ipc_channel_t*c){if(!c)return -1;uint64_t f;rix_spin_lock_irqsave(&c->lock,&f);c->closed=1;rix_spin_unlock_irqrestore(&c->lock,f);return 0;}
